/* ---------------------------------------------------------------------
   1) CHARGEMENT / PERSISTANCE (local)
   --------------------------------------------------------------------- */
let DP = dpLoad();

function dpLoad() {
  try {
    const raw = localStorage.getItem(DP_STORAGE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) { /* ignore, on retombe sur le seed */ }
  const fresh = JSON.parse(JSON.stringify(DP_SEED));
  localStorage.setItem(DP_STORAGE_KEY, JSON.stringify(fresh));
  return fresh;
}

function dpPersist() {
  localStorage.setItem(DP_STORAGE_KEY, JSON.stringify(DP));
}

function dpResetDemo() {
  if (!confirm("Réinitialiser les données locales à partir des fichiers source ? Toute modification sera perdue.")) return;
  localStorage.removeItem(DP_STORAGE_KEY);
  window.location.reload();
}

/* ---------------------------------------------------------------------
   2) AUTHENTIFICATION — identifiant + mot de passe (SHA-256 + sel, pattern DomPilot/GESTOCK)
   --------------------------------------------------------------------- */
function dpGetSession() {
  try { return JSON.parse(sessionStorage.getItem(DP_SESSION_KEY) || "null"); }
  catch (e) { return null; }
}

function dpRandomSalt() {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr).map(b => b.toString(16).padStart(2, "0")).join("");
}

async function dpHashPassword(password, salt) {
  const enc = new TextEncoder();
  const data = enc.encode(salt + ":" + password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hashBuffer)).map(b => b.toString(16).padStart(2, "0")).join("");
}

/* Retourne { status: "ok" | "notfound" | "wrongpassword" | "firstlogin", user } */
async function dpAttemptLogin(identifiant, password) {
  const u = DP.utilisateurs.find(x => x.identifiant.toLowerCase() === String(identifiant).toLowerCase().trim());
  if (!u) return { status: "notfound", user: null };
  if (!u.passwordHash) return { status: "firstlogin", user: u };
  const hash = await dpHashPassword(password, u.passwordSalt);
  if (hash !== u.passwordHash) return { status: "wrongpassword", user: u };
  sessionStorage.setItem(DP_SESSION_KEY, JSON.stringify({ identifiant: u.identifiant, nom: u.nom }));
  return { status: "ok", user: u };
}

/* Définit (ou réinitialise) le mot de passe d'un utilisateur et connecte la session */
async function dpSetPassword(identifiant, newPassword, autoLogin) {
  const u = DP.utilisateurs.find(x => x.identifiant.toLowerCase() === String(identifiant).toLowerCase().trim());
  if (!u) return false;
  const salt = dpRandomSalt();
  u.passwordSalt = salt;
  u.passwordHash = await dpHashPassword(newPassword, salt);
  dpAutoSync();
  if (autoLogin) sessionStorage.setItem(DP_SESSION_KEY, JSON.stringify({ identifiant: u.identifiant, nom: u.nom }));
  return true;
}

function dpLogout() {
  sessionStorage.removeItem(DP_SESSION_KEY);
  window.location.href = "index.html";
}

function dpRequireAuth() {
  const session = dpGetSession();
  if (!session) { window.location.href = "index.html"; return null; }
  return true;
}

function dpCurrentUser() {
  const s = dpGetSession();
  if (!s) return null;
  return DP.utilisateurs.find(u => u.identifiant === s.identifiant) || null;
}

/* ---------------------------------------------------------------------
   3) SYNCHRONISATION GITHUB — ARCHITECTURE À DEUX DÉPÔTS (pattern DomPilot/GESTOCK)
   - Dépôt PUBLIC : héberge ce code (index.html, *.html, style.css, app.js)
     via GitHub Pages. Aucune donnée sensible n'y transite.
   - Dépôt PRIVÉ : contient uniquement data.json (sites, contrats, annuaire,
     utilisateurs). Owner/repo/chemin sont fixes (ci-dessous) — seul le
     token doit être renseigné une fois par appareil, depuis Paramètres.
   --------------------------------------------------------------------- */
const DP_GITHUB_REPO = { owner: "Domoimmo", repo: "dompilot-immobilier-data", path: "data.json" };

function dpGetGithubConfig() {
  const token = localStorage.getItem("dompatrimoine_github_token");
  if (!token) return null;
  return { ...DP_GITHUB_REPO, token };
}

function dpSaveGithubToken(token) {
  if (token) localStorage.setItem("dompatrimoine_github_token", token);
  else localStorage.removeItem("dompatrimoine_github_token");
}

async function dpSyncWithGitHub() {
  const cfg = dpGetGithubConfig();
  const statusEl = document.getElementById("github-sync-status");
  if (!cfg || !cfg.token || !cfg.owner || !cfg.repo) {
    if (statusEl) statusEl.textContent = "Configurez le dépôt de données dans Paramètres";
    return false;
  }
  if (statusEl) statusEl.textContent = "Synchronisation…";
  try {
    const path = cfg.path || "data.json";
    const apiUrl = `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents/${path}`;
    let sha = null;
    const getResp = await fetch(apiUrl, { headers: { Authorization: `token ${cfg.token}` } });
    if (getResp.ok) { const j = await getResp.json(); sha = j.sha; }
    const content = btoa(unescape(encodeURIComponent(JSON.stringify(DP, null, 2))));
    const putResp = await fetch(apiUrl, {
      method: "PUT",
      headers: { Authorization: `token ${cfg.token}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        message: `DomPatrimoine: mise à jour des données — ${new Date().toISOString()}`,
        content, sha: sha || undefined
      })
    });
    if (!putResp.ok) throw new Error("Échec de l'écriture GitHub");
    if (statusEl) statusEl.textContent = `Synchronisé avec ${cfg.owner}/${cfg.repo} ✓`;
    return true;
  } catch (err) {
    if (statusEl) statusEl.textContent = "Erreur de synchronisation";
    console.error(err);
    return false;
  }
}

async function dpLoadFromGitHub() {
  const cfg = dpGetGithubConfig();
  if (!cfg || !cfg.token || !cfg.owner || !cfg.repo) return false;
  try {
    const path = cfg.path || "data.json";
    const apiUrl = `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents/${path}`;
    const resp = await fetch(apiUrl, { headers: { Authorization: `token ${cfg.token}` } });
    if (!resp.ok) return false;
    const j = await resp.json();
    const raw = decodeURIComponent(escape(atob(j.content)));
    const remote = JSON.parse(raw);
    DP = remote;
    dpPersist();
    return true;
  } catch (err) {
    console.error(err);
    return false;
  }
}

/* ---------------------------------------------------------------------
   4) SHELL DE NAVIGATION COMMUN
   --------------------------------------------------------------------- */
const DP_NAV = [
  { key: "dashboard",   href: "dashboard.html",   ico: "&#9635;", label: "Tableau de bord" },
  { key: "patrimoine",  href: "patrimoine.html",  ico: "&#127970;", label: "Patrimoine" },
  { key: "carte",       href: "carte.html",       ico: "&#128506;", label: "Carte" },
  { key: "contrats",    href: "contrats.html",    ico: "&#128196;", label: "Contrats" },
  { key: "annuaire",    href: "annuaire.html",    ico: "&#9742;",  label: "Annuaire prestataires" },
  { key: "parametres",  href: "parametres.html",  ico: "&#9881;",  label: "Paramètres" }
];

function dpRenderShell(activeKey, pageTitle, pageSubtitle) {
  if (!dpRequireAuth()) return null;
  const user = dpCurrentUser();

  // Si un dépôt privé est configuré, on rafraîchit les données en arrière-plan
  // (le rendu initial utilise d'abord le cache local pour un affichage instantané).
  if (dpGetGithubConfig()) {
    dpLoadFromGitHub().then(ok => { if (ok && typeof render === "function") render(); });
  }

  document.body.innerHTML = `
    <div class="app-shell">
      <div class="sidebar">
        <div class="brand">
          <div class="logo-mark">DP</div>
          <div class="brand-text"><strong>DomPatrimoine</strong><span>Services Généraux</span></div>
        </div>
        <div class="nav-group">
          <div class="nav-label">Navigation</div>
          ${DP_NAV.map(n => `
            <div class="nav-link ${n.key === activeKey ? 'active' : ''}" onclick="window.location.href='${n.href}'">
              <span class="ico">${n.ico}</span><span>${n.label}</span>
            </div>`).join("")}
        </div>
        <div class="sidebar-footer">
          <div class="user-row">&#128100; ${dpEsc(user ? user.nom : "")}</div>
          <button class="logout-btn" onclick="dpLogout()">Déconnexion</button>
        </div>
      </div>
      <div class="main">
        <div class="topbar">
          <div>
            <h1>${dpEsc(pageTitle)}</h1>
            <div class="subtitle">${dpEsc(pageSubtitle || "")}</div>
          </div>
          <div class="text-muted" id="github-sync-status">${dpGetGithubConfig() ? "Connecté au dépôt de données" : "Mode local &middot; non synchronisé avec GitHub"}</div>
        </div>
        <div class="content" id="dp-content"></div>
      </div>
    </div>
    <button class="back-to-top" id="dp-back-to-top" onclick="window.scrollTo({top:0,behavior:'smooth'})" aria-label="Retour en haut" title="Retour en haut">&#8593;</button>
  `;

  const backBtn = document.getElementById("dp-back-to-top");
  window.addEventListener("scroll", () => {
    if (window.scrollY > 300) backBtn.classList.add("show");
    else backBtn.classList.remove("show");
  });

  return document.getElementById("dp-content");
}

/* ---------------------------------------------------------------------
   5) HELPERS
   --------------------------------------------------------------------- */
function dpEsc(str) {
  if (str === null || str === undefined) return "";
  return String(str)
    .replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;").replaceAll("'", "&#39;");
}

function dpFormatDate(iso) {
  if (!iso) return "&mdash;";
  const d = new Date(iso);
  if (isNaN(d)) return dpEsc(iso);
  return d.toLocaleDateString("fr-FR");
}

function dpFormatNumber(n, digits) {
  if (n === null || n === undefined || n === "") return "&mdash;";
  return Number(n).toLocaleString("fr-FR", { maximumFractionDigits: digits ?? 1 });
}

function dpUniqueSorted(arr) {
  return Array.from(new Set(arr.filter(v => v !== null && v !== undefined && v !== ""))).sort((a, b) =>
    String(a).localeCompare(String(b), "fr"));
}

function dpToday() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function dpDebounce(fn, wait) {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), wait || 200); };
}

/* ---------------------------------------------------------------------
   6) CRÉATION / ÉDITION GÉNÉRIQUE (formulaires patrimoine, contrats, annuaire)
   --------------------------------------------------------------------- */
function dpGenId(prefix) {
  return `${prefix}-${Date.now().toString(36)}${Math.floor(Math.random() * 1000)}`;
}

function dpRenderFormFields(fields, values) {
  return fields.map(f => {
    const val = values[f.key] ?? "";
    if (f.type === "select") {
      return `<div class="field"><label>${dpEsc(f.label)}</label><select id="ff-${f.key}">
        ${f.options.map(o => `<option value="${dpEsc(o)}" ${String(val) === String(o) ? "selected" : ""}>${dpEsc(f.optionLabels ? f.optionLabels[o] : o)}</option>`).join("")}
      </select></div>`;
    }
    if (f.type === "textarea") {
      return `<div class="field"><label>${dpEsc(f.label)}</label><textarea id="ff-${f.key}" rows="2">${dpEsc(val)}</textarea></div>`;
    }
    return `<div class="field"><label>${dpEsc(f.label)}${f.required ? " *" : ""}</label><input id="ff-${f.key}" type="${f.type || "text"}" value="${dpEsc(val)}"></div>`;
  }).join("");
}

function dpReadFormFields(fields) {
  const out = {};
  fields.forEach(f => {
    const el = document.getElementById("ff-" + f.key);
    if (!el) return;
    let v = el.value;
    if (f.type === "number") v = v === "" ? null : Number(v);
    if (typeof v === "string") v = v.trim();
    out[f.key] = v;
  });
  return out;
}

function dpValidateRequired(fields, values) {
  const missing = fields.filter(f => f.required && !values[f.key]);
  return missing;
}

/* Synchronisation automatique en arrière-plan après une modification,
   si un dépôt GitHub est configuré (sinon les données restent locales). */
function dpAutoSync() {
  dpPersist();
  if (dpGetGithubConfig()) dpSyncWithGitHub();
}

/* ---------------------------------------------------------------------
   7) ÉCHÉANCES DE CONTRAT
   --------------------------------------------------------------------- */
function dpEcheanceInfo(dateEcheance) {
  if (!dateEcheance) return { label: "Non renseignée", cls: "badge-gray", days: null };
  const d = new Date(dateEcheance);
  if (isNaN(d)) return { label: "Non renseignée", cls: "badge-gray", days: null };
  const days = Math.ceil((d - new Date(new Date().toDateString())) / 86400000);
  if (days < 0) return { label: `Échu depuis ${dpFormatDate(dateEcheance)}`, cls: "badge-red", days };
  if (days <= 60) return { label: `Dans ${days} j &middot; ${dpFormatDate(dateEcheance)}`, cls: "badge-orange", days };
  return { label: dpFormatDate(dateEcheance), cls: "badge-green", days };
}

/* ---------------------------------------------------------------------
   8) EXPORT EXCEL (CSV compatible Excel, séparateur ";", sans dépendance)
   --------------------------------------------------------------------- */
function dpExportCSV(filename, headers, rows) {
  const escCell = v => {
    if (v === null || v === undefined) return "";
    let s = String(v);
    if (/[;"\n]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
    return s;
  };
  const lines = [headers.map(escCell).join(";")];
  rows.forEach(r => lines.push(r.map(escCell).join(";")));
  const csv = "\uFEFF" + lines.join("\r\n"); // BOM UTF-8 pour les accents dans Excel
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
